/// features > biblioteca > data > library_manifest — Dart mirror of
/// `library.json` (schema: book/schemas/libretapp-library.schema.json),
/// generated by tools/generate_library_manifest.ps1 in the content repo and
/// bundled at assets/library/library.json by tool/sync_library_assets.ps1.
///
/// This is the "book of books" catalog: one entry per subject book
/// (Agricultura, Bovinos, Caprinos, Equinos, Mascotas, Suelos, Ovinos). The
/// library screen renders this list; opening a book then loads its full
/// content from `assets/library/<book_id>/content/book-content.json` (see
/// book_content.dart).
library;

import 'package:equatable/equatable.dart';

class LibraryAdaptiveSummary {
  const LibraryAdaptiveSummary({
    required this.enabled,
    required this.supportedRegions,
    this.pilotState,
    this.selectionPrecedence = const [],
  });

  factory LibraryAdaptiveSummary.fromJson(Map<String, dynamic> json) =>
      LibraryAdaptiveSummary(
        enabled: json['enabled'] as bool? ?? false,
        supportedRegions: List<String>.from(
          json['supported_regions'] as List? ?? const [],
        ),
        pilotState: json['pilot_state'] as String?,
        selectionPrecedence: List<String>.from(
          json['selection_precedence'] as List? ?? const [],
        ),
      );

  final bool enabled;
  final List<String> supportedRegions;
  final String? pilotState;
  final List<String> selectionPrecedence;
}

class LibraryManifestBook extends Equatable {
  const LibraryManifestBook({
    required this.bookId,
    required this.subject,
    required this.packageDir,
    required this.title,
    required this.subtitle,
    required this.description,
    required this.language,
    required this.translationStatus,
    required this.tags,
    required this.stats,
    required this.adaptive,
    required this.contentPath,
    this.primarySpecies,
  });

  factory LibraryManifestBook.fromJson(Map<String, dynamic> json) =>
      LibraryManifestBook(
        bookId: json['book_id'] as String? ?? '',
        subject: json['subject'] as String? ?? '',
        packageDir: json['package_dir'] as String? ?? '',
        title: json['title'] as String? ?? '',
        subtitle: json['subtitle'] as String? ?? '',
        description: json['description'] as String? ?? '',
        primarySpecies: json['primary_species'] as String?,
        language: json['language'] as String? ?? 'es',
        translationStatus: json['translation_status'] as String? ?? '',
        tags: List<String>.from(json['tags'] as List? ?? const []),
        stats: Map<String, dynamic>.from(json['stats'] as Map? ?? const {}),
        adaptive: LibraryAdaptiveSummary.fromJson(
          json['adaptive'] as Map<String, dynamic>? ?? const {},
        ),
        contentPath: json['content_path'] as String? ?? 'content/book-content.json',
      );

  final String bookId;
  final String subject;
  final String packageDir;
  final String title;
  final String subtitle;
  final String description;
  final String? primarySpecies;
  final String language;
  final String translationStatus;
  final List<String> tags;
  final Map<String, dynamic> stats;
  final LibraryAdaptiveSummary adaptive;
  final String contentPath;

  /// Asset path to this book's compiled content, relative to the Flutter
  /// asset bundle root — see pubspec.yaml's `assets/library/<book_id>/...`
  /// entries and tool/sync_library_assets.ps1.
  String get contentAssetPath => assetPath(contentPath);

  /// Resolves a path relative to this book's package dir (e.g. a
  /// [Figure.path] like `assets/figures/x.svg`) to a full Flutter asset
  /// path bundled by tool/sync_library_assets.ps1.
  String assetPath(String relativePath) => 'assets/library/$packageDir/$relativePath';

  int get mainChapters => (stats['main_chapters'] as num?)?.toInt() ?? 0;

  @override
  List<Object?> get props => [bookId, title];
}

class LibraryManifest {
  const LibraryManifest({required this.generatedAt, required this.books});

  factory LibraryManifest.fromJson(Map<String, dynamic> json) =>
      LibraryManifest(
        generatedAt: json['generated_at'] as String? ?? '',
        books: (json['books'] as List<dynamic>? ?? const [])
            .map((e) => LibraryManifestBook.fromJson(e as Map<String, dynamic>))
            .toList(growable: false),
      );

  final String generatedAt;
  final List<LibraryManifestBook> books;
}
